  const [note, setNote] = useState("");
  const [noteError, setNoteError] = useState("");
  const [noteSaved, setNoteSaved] = useState(false);

  const now = new Date();
  const todayISO = now.toISOString().slice(0, 10);
  const todayDate = toDate(todayISO);

  const completedCount = tasks.filter((task) => task.completed).length;
  const progressValue = tasks.length ? Math.round((completedCount / tasks.length) * 100) : 0;

  const quickTasks = useMemo(() => {
    return orderedIds
      .map((id) => tasks.find((task) => task.id === id))
      .filter((task): task is Task => Boolean(task));
  }, [orderedIds, tasks]);

  const filteredQuickTasks = useMemo(() => {
    return quickTasks.filter((task) => {
      if (filter === "today") {
        return task.dueDate === todayISO;
      }
      if (filter === "overdue") {
        return toDate(task.dueDate) < todayDate && !task.completed;
      }
      return true;
    });
  }, [quickTasks, filter, todayISO, todayDate]);

  const handleNoteSubmit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (note.trim().length < 5) {
      setNoteError("Введите не менее 5 символов, чтобы заметка была полезной.");
      setNoteSaved(false);
      return;
    }
    setNoteError("");
    setNote("");
    setNoteSaved(true);
    window.setTimeout(() => setNoteSaved(false), 1800);
  };

  const toggleTaskComplete = (taskId: string, next: boolean) => {
    setTasks((prev) =>
      prev.map((task) => {
        if (task.id !== taskId) {
          return task;
        }
        const updatedSubtasks = task.subtasks.map((subtask) => ({
          ...subtask,
          done: next ? true : subtask.done,
        }));
        return {
          ...task,
          completed: next,
          status: next ? "done" : task.status === "done" ? "inProgress" : task.status,
          subtasks: updatedSubtasks,
        };
      })
    );
  };

  const toggleSubtask = (taskId: string, subtaskId: string, next: boolean) => {
    setTasks((prev) =>
      prev.map((task) => {
        if (task.id !== taskId) {
          return task;
        }
        const updatedSubtasks = task.subtasks.map((subtask) =>
          subtask.id === subtaskId ? { ...subtask, done: next } : subtask
        );
        const allDone = updatedSubtasks.every((subtask) => subtask.done);
        return {
          ...task,
          subtasks: updatedSubtasks,
          completed: allDone,
          status: allDone ? "done" : task.status === "done" ? "inProgress" : task.status,
        };
      })
    );
  };

  const handleDragStart = (taskId: string) => (event: React.DragEvent<HTMLDivElement>) => {
    event.dataTransfer.setData("text/plain", taskId);
    event.dataTransfer.effectAllowed = "move";
  };

  const handleDrop = (targetId: string) => (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    const sourceId = event.dataTransfer.getData("text/plain");
    if (!sourceId || sourceId === targetId) {
      return;
    }
    setOrderedIds((prev) => {
      if (!prev.includes(sourceId)) {
        return prev;
      }
      const nextOrder = prev.filter((id) => id !== sourceId);
      const targetIndex = nextOrder.indexOf(targetId);
      if (targetIndex === -1) {
        nextOrder.push(sourceId);
        return [...nextOrder];
      }
      nextOrder.splice(targetIndex, 0, sourceId);
      return [...nextOrder];
    });
  };

  const handleDragOver = (event: React.DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    event.dataTransfer.dropEffect = "move";
  };

  const isOverdue = (task: Task) => toDate(task.dueDate) < todayDate && !task.completed;

  return (
    <div className="min-h-screen bg-background text-foreground">
      <main className="mx-auto flex max-w-5xl flex-col gap-8 px-4 py-10">
        <section className="animate-in fade-in slide-in-from-right-4 duration-250">
          <Card className="bg-card shadow-sm">
            <CardHeader className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
              <div className="flex items-center gap-3">
                <div className="rounded-2xl bg-primary/15 p-3 text-primary">
                  <Home className="h-6 w-6" />
                </div>
                <div>
                  <CardTitle className="text-2xl">App · Таск-менеджер</CardTitle>
                  <CardDescription className="text-base text-muted-foreground">
                    Продолжи: аккуратно нарастим функциональность для General user и сохраним чистый интерфейс.
                  </CardDescription>
                </div>
              </div>
              <div className="flex items-center gap-2 rounded-xl bg-muted px-4 py-2 text-sm text-muted-foreground">
                <CheckCircle2 className="h-4 w-4" />
                Прогресс недели · {progressValue}%
              </div>
            </CardHeader>
            <CardContent className="space-y-6">
              <div className="space-y-2">
                <div className="text-sm font-medium text-muted-foreground">Быстрая заметка</div>
                <form onSubmit={handleNoteSubmit} className="flex flex-col gap-3 sm:flex-row">
                  <Input
                    value={note}
                    onChange={(event) => setNote(event.target.value)}
                    placeholder="Зафиксируйте идею или важный блок задач"
                    className="min-h-[48px] flex-1"
                  />
                  <Button
                    type="submit"
                    className="min-h-[48px] flex-1 transition-all duration-200 active:scale-95 sm:flex-none"
                  >
                    Сохранить мысль
                  </Button>
                </form>
                {noteError && <p className="text-sm text-destructive">{noteError}</p>}
                {noteSaved && (
                  <p className="text-sm font-medium text-primary animate-in fade-in zoom-in-50 duration-200">
                    Заметка зафиксирована, можно продолжать.
                  </p>
                )}
              </div>
              <div className="space-y-3">
                <div className="flex items-center justify-between text-sm text-muted-foreground">
                  <span>Выполнено задач</span>
                  <span>
                    {completedCount}/{tasks.length}
                  </span>
                </div>
                <Progress value={progressValue} className="h-2" />
              </div>
            </CardContent>
          </Card>
        </section>

        <section className="space-y-5 animate-in fade-in slide-in-from-right-4 duration-250">
          <header className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <h2 className="text-xl font-semibold">Список фокуса</h2>
              <p className="text-sm text-muted-foreground">Перетаскивайте карточки и отмечайте чекбоксы, чтобы держать приоритеты под контролем.</p>
            </div>
            <div className="flex gap-2">
              {filters.map((option) => (
                <Button
                  key={option.key}
                  type="button"
                  variant={filter === option.key ? "default" : "ghost"}
                  className="rounded-full px-4 py-2 text-sm transition-all duration-200"
                  onClick={() => setFilter(option.key)}
                >
                  {option.label}
                </Button>
              ))}
            </div>
          </header>
          <div role="list" className="space-y-4">
            {filteredQuickTasks.length === 0 ? (
              <div className="animate-in fade-in zoom-in-95 duration-500 delay-100 rounded-2xl border border-dashed border-border bg-card px-6 py-12 text-center text-muted-foreground">
                <div className="text-4xl mb-3">📝</div>
                <p className="text-base font-semibold">Пока нет задач в этой выборке</p>
                <p className="text-sm">Сбросьте фильтр или добавьте новую карточку, чтобы начать.</p>
              </div>
            ) : (
              filteredQuickTasks.map((task, index) => {
                const completedSubtasks = task.subtasks.filter((subtask) => subtask.done).length;
                const totalSubtasks = task.subtasks.length;
                const columnProgress = totalSubtasks
                  ? Math.round((completedSubtasks / totalSubtasks) * 100)
                  : task.completed
                  ? 100
                  : 0;
                return (
                  <article
                    key={task.id}
                    role="listitem"
                    draggable
                    onDragStart={handleDragStart(task.id)}
                    onDragOver={handleDragOver}
                    onDrop={handleDrop(task.id)}
                    aria-grabbed={false}
                    className="group rounded-2xl border border-border bg-card p-4 shadow-sm transition-all duration-200 hover:shadow-md"
                    style={{ animationDelay: `${index * 50}ms` }}
                  >
                    <div className="flex items-start gap-3">
                      <GripVertical className="mt-1 h-4 w-4 text-muted-foreground" />
                      <Checkbox
                        checked={task.completed}
                        onCheckedChange={(checked: CheckedState) => toggleTaskComplete(task.id, checked === true)}
                        className="mt-1"
                      />
                      <div className="flex-1 space-y-2">
                        <div className="flex flex-wrap items-center gap-2">
                          <p className="text-base font-semibold leading-tight">{task.title}</p>
                          <Badge variant="outline" className={`${priorityCopy[task.priority].tone} capitalize`}>
                            {priorityCopy[task.priority].label}
                          </Badge>
                          <Badge variant="secondary">{task.project}</Badge>
                        </div>
                        <p className="text-sm text-muted-foreground line-clamp-2">{task.description}</p>
                        <div className="flex flex-wrap items-center gap-3 text-xs font-medium text-muted-foreground">
                          <div className={`rounded-full px-3 py-1 ${isOverdue(task) ? "bg-destructive/10 text-destructive" : "bg-muted"}`}>
                            {isOverdue(task) ? "Просрочено" : `До ${formatDate(task.dueDate)}`}
                          </div>
                          <div className="flex items-center gap-1">
                            <CalendarDays className="h-4 w-4" />
                            {formatDate(task.dueDate)}
                          </div>
                          <div className="flex items-center gap-1">
                            <CheckCircle2 className="h-4 w-4" />
                            {completedSubtasks}/{totalSubtasks} подзадач
                          </div>
                        </div>
                        <div className="space-y-2">
                          <Progress value={columnProgress} className="h-1.5" />
                          <div className="flex justify-between text-xs text-muted-foreground">
                            <span>Прогресс</span>
                            <span>{columnProgress}%</span>
                          </div>
                        </div>
                        <div className="space-y-2">
                          {task.subtasks.length === 0 ? (
                            <div className="rounded-xl bg-muted px-3 py-2 text-xs text-muted-foreground">
                              Подзадачи пока не заведены.
                            </div>
                          ) : (
                            task.subtasks.map((subtask) => (
                              <div key={subtask.id} className="flex items-start gap-2 pl-6">
                                <Checkbox
                                  checked={subtask.done}
                                  onCheckedChange={(checked: CheckedState) =>
                                    toggleSubtask(task.id, subtask.id, checked === true)
                                  }
                                  className="mt-[2px]"
                                />
                                <p className={`text-sm ${subtask.done ? "text-muted-foreground line-through" : "text-foreground"}`}>
                                  {subtask.title}
                                </p>
                              </div>
                            ))
                          )}
                        </div>
                      </div>
                    </div>
                  </article>
                );
              })
            )}
          </div>
        </section>

        <section className="space-y-4 animate-in fade-in slide-in-from-right-4 duration-250">
          <header className="flex flex-col gap-2">
            <h2 className="text-xl font-semibold">Канбан-лента</h2>
            <p className="text-sm text-muted-foreground">Раскладываем задачи по статусам, чтобы видеть узкие места.</p>
          </header>
          <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-4">
            {statusColumns.map((column) => {
              const columnTasks = tasks.filter((task) => task.status === column.key);
              return (
                <div
                  key={column.key}
                  className="rounded-2xl border border-border bg-card p-4 shadow-sm"
                >
                  <div className="flex items-start justify-between">
                    <div>
                      <p className="text-base font-semibold">{column.label}</p>
                      <p className="text-sm text-muted-foreground">{column.helper}</p>
                    </div>
                    <Badge variant="outline" className="text-sm">
                      {columnTasks.length}
                    </Badge>
                  </div>
                  <Separator className="my-4" />
                  {columnTasks.length === 0 ? (
                    <div className="animate-in fade-in zoom-in-95 duration-500 delay-100 rounded-xl border border-dashed border-border bg-muted/60 px-3 py-6 text-center text-muted-foreground">
                      <div className="text-3xl mb-2">🗂️</div>
                      <p className="text-sm font-medium">Нет карточек</p>
                      <p className="text-xs">Перетащите задачу сюда, когда она попадёт в этот этап.</p>
                    </div>
                  ) : (
                    <div className="space-y-3 max-h-[60vh] overflow-y-auto pr-1">
                      {columnTasks.map((task, index) => (
                        <article
                          key={task.id}
                          className="animate-in fade-in slide-in-from-bottom-2 duration-300 rounded-2xl border border-border bg-background/80 p-3 hover:shadow-md"
                          style={{ animationDelay: `${index * 40}ms` }}
                        >
                          <p className="text-sm font-semibold truncate">{task.title}</p>
                          <p className="text-xs text-muted-foreground line-clamp-2">{task.description}</p>
                          <div className="mt-3 flex flex-wrap items-center gap-2 text-xs text-muted-foreground">
                            <span className="rounded-full bg-muted px-2 py-0.5">{formatDate(task.dueDate)}</span>
                            <span className={`rounded-full px-2 py-0.5 ${priorityCopy[task.priority].tone}`}>
                              {priorityCopy[task.priority].label}
                            </span>
                            <span className="rounded-full bg-secondary/40 px-2 py-0.5 text-secondary-foreground">
                              {task.project}
                            </span>
                          </div>
                        </article>
                      ))}
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </section>
      </main>
    </div>
  );
